        self.assertEqual(order_total([(1.0, 20), (1.0, 20)]), 39.93)

    def test_bulk_order_discount_does_not_apply_below_40_items(self):
        self.assertEqual(order_total([(1.0, 39)]), 42.12)


if __name__ == "__main__":
    unittest.main()
"}

