    def test_low_stock_threshold_can_be_overridden(self):
        with patch.dict(os.environ, {"LOW_STOCK_THRESHOLD": "5"}):
            self.assertEqual(low_stock(ITEMS), ["nut"])


if __name__ == "__main__":
