{"path":"app/pricing.py","content":""""Order pricing."""

from app.config import BULK_DISCOUNT_ITEM_THRESHOLD, BULK_DISCOUNT_RATE, TAX_RATE


def line_total(unit_price, quantity):
    return round(unit_price * quantity, 2)


def order_total(lines):
    """Return the taxed order total, applying bulk discounts before tax."""
    subtotal = sum(line_total(price, qty) for price, qty in lines)
    item_count = sum(quantity for _, quantity in lines)
    if item_count >= BULK_DISCOUNT_ITEM_THRESHOLD:
        subtotal *= 1 - BULK_DISCOUNT_RATE
    return round(subtotal * (1 + TAX_RATE), 2)
"}

