{"path":"app/pricing.py","content":""""Order pricing."""

from app import config


def line_total(unit_price, quantity):
    return round(unit_price * quantity, 2)


def order_total(lines):
    """Return the order total after any bulk discount and tax.

    Lines are (unit_price, quantity) pairs. The bulk discount is applied to
    the subtotal before tax when the total quantity reaches the configured
    minimum.
    """
    lines = list(lines)
    subtotal = sum(line_total(price, qty) for price, qty in lines)
    total_quantity = sum(qty for _, qty in lines)

    if total_quantity >= config.BULK_DISCOUNT_MIN_ITEMS:
        subtotal *= 1 - config.BULK_DISCOUNT_RATE

    return round(subtotal * (1 + config.TAX_RATE), 2)
"}

{"path":"tests/test_pricing.py","content":"import unittest

from app.pricing import line_total, order_total


class PricingTest(unittest.TestCase):
    def test_line_total(self):
        self.assertEqual(line_total(2.5, 4), 10.0)

    def test_order_total_adds_tax(self):
        self.assertEqual(order_total([(10.0, 1)]), 10.8)

    def test_bulk_discount_applies_at_40_items_before_tax(self):
        # 40 * $10 = $400; 7% discount gives $372, then 8% tax gives $401.76.
        self.assertEqual(order_total([(10.0, 40)]), 401.76)

    def test_bulk_discount_counts_items_across_lines(self):
        self.assertEqual(order_total([(10.0, 20), (10.0, 20)]), 401.76)

    def test_bulk_discount_does_not_apply_below_40_items(self):
        self.assertEqual(order_total([(10.0, 39)]), 421.2)


if __name__ == "__main__":
    unittest.main()
"}

