{"path":"app/pricing.py","content":""""Order pricing."""

from app.config import (
    BULK_ORDER_DISCOUNT_MIN_ITEMS,
    BULK_ORDER_DISCOUNT_RATE,
    ORDER_TAX_RATE,
)


def line_total(unit_price, quantity):
    return round(unit_price * quantity, 2)


def order_total(lines):
    """Return the tax-inclusive total for a list of (unit_price, quantity) pairs."""
    subtotal = sum(line_total(price, qty) for price, qty in lines)
    item_count = sum(quantity for _, quantity in lines)
    discount_rate = (
        BULK_ORDER_DISCOUNT_RATE
        if item_count >= BULK_ORDER_DISCOUNT_MIN_ITEMS
        else 0
    )
    discounted_subtotal = subtotal * (1 - discount_rate)
    return round(discounted_subtotal * (1 + ORDER_TAX_RATE), 2)
"}

{"path":"tests/test_pricing.py","content":"import unittest

from app.pricing import line_total, order_total


class PricingTest(unittest.TestCase):
    def test_line_total(self):
        self.assertEqual(line_total(2.5, 4), 10.0)

    def test_order_total_adds_tax(self):
        self.assertEqual(order_total([(10.0, 1)]), 10.8)

    def test_bulk_discount_applies_at_40_items_before_tax(self):
        self.assertEqual(order_total([(1.0, 40)]), 39.74)

    def test_bulk_discount_does_not_apply_below_40_items(self):
        self.assertEqual(order_total([(1.0, 39)]), 42.12)

    def test_item_count_is_combined_across_lines(self):
        self.assertEqual(order_total([(1.0, 20), (1.0, 20)]), 39.74)


if __name__ == "__main__":
    unittest.main()
"}

