{"path":"app/inventory.py","content":""""Inventory queries."""

from app.config import LOW_STOCK_THRESHOLD


def total_quantity(items):
    """Sum the quantity of every item. Items are dicts with name and quantity."""
    return sum(item["quantity"] for item in items)


def find(items, name):
    """Return the item called `name`, or None."""
    for item in items:
        if item["name"] == name:
            return item
    return None


def low_stock(items):
    """Return names of items below the low-stock threshold, alphabetically."""
    return sorted(
        item["name"] for item in items if item["quantity"] < LOW_STOCK_THRESHOLD
    )
"}

{"path":"tests/test_inventory.py","content":"import unittest

from app.inventory import find, low_stock, total_quantity

ITEMS = [{"name": "bolt", "quantity": 30}, {"name": "nut", "quantity": 4}]


class InventoryTest(unittest.TestCase):
    def test_total_quantity(self):
        self.assertEqual(total_quantity(ITEMS), 34)

    def test_find(self):
        self.assertEqual(find(ITEMS, "nut")["quantity"], 4)
        self.assertIsNone(find(ITEMS, "gear"))

    def test_low_stock_filters_and_sorts_names(self):
        items = [
            {"name": "zinc", "quantity": 11},
            {"name": "alpha", "quantity": 0},
            {"name": "threshold", "quantity": 12},
            {"name": "plum", "quantity": 3},
        ]
        self.assertEqual(low_stock(items), ["alpha", "plum", "zinc"])

    def test_low_stock_empty_items(self):
        self.assertEqual(low_stock([]), [])


if __name__ == "__main__":
    unittest.main()
"}

